import React, { useState, useEffect } from 'react';
import io from 'socket.io-client';
import GameBoard from './components/GameBoard';
import PlayerInfo from './components/PlayerInfo';
import ActionPanel from './components/ActionPanel';
import JoinForm from './components/JoinForm';
import SkeletalApp from './SkeletalApp';

const socket = io('http://localhost:3001');

function App() {
  const [gameState, setGameState] = useState(null);
  const [playerId, setPlayerId] = useState(null);
  const [playerCards, setPlayerCards] = useState([]);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const [isJoined, setIsJoined] = useState(false);
  const [useSkeletal, setUseSkeletal] = useState(false);

  // Check URL parameter for skeletal mode
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.get('mode') === 'skeletal') {
      setUseSkeletal(true);
    }
  }, []);

  // If skeletal mode is enabled, use the skeletal app
  if (useSkeletal) {
    return <SkeletalApp />;
  }

  useEffect(() => {
    // Socket event listeners
    socket.on('gameJoined', (data) => {
      setPlayerId(data.playerId);
      setGameState(data.gameState);
      setIsJoined(true);
      setError('');
      setMessage('Successfully joined the game!');
    });

    socket.on('gameStateUpdate', (data) => {
      setGameState(data);
    });

    socket.on('playerJoined', (data) => {
      setMessage(
        `${data.player.name} joined the game as ${data.player.character}`
      );
    });

    socket.on('playerLeft', (data) => {
      setMessage('A player left the game');
    });

    socket.on('gameStarted', (data) => {
      setGameState(data.gameState);
      setMessage('Game has started!');
    });

    socket.on('moveResult', (data) => {
      if (data.success) {
        setMessage('Move successful!');
        if (data.mustMakeSuggestion) {
          setMessage('Move successful! You must now make a suggestion.');
        }
      }
    });

    socket.on('suggestionMade', (data) => {
      if (data.success) {
        setMessage(
          `${data.suggestedBy} suggests: ${data.suggestion.character} with ${data.suggestion.weapon} in ${data.suggestion.room}`
        );
      }
    });

    socket.on('accusationMade', (data) => {
      if (data.correct) {
        setMessage(
          `${data.accusedBy} wins! Correct accusation: ${data.accusation.character} with ${data.accusation.weapon} in ${data.accusation.room}`
        );
      } else {
        setMessage(
          `${data.accusedBy} made an incorrect accusation and is eliminated!`
        );
      }
    });

    socket.on('gameEnded', (data) => {
      if (data.winner) {
        setMessage(`Game Over! ${data.winner.name} wins!`);
      } else {
        setMessage(`Game ended: ${data.reason}`);
      }
    });

    socket.on('error', (data) => {
      setError(data.message);
    });

    return () => {
      socket.off('gameJoined');
      socket.off('gameStateUpdate');
      socket.off('playerJoined');
      socket.off('playerLeft');
      socket.off('gameStarted');
      socket.off('moveResult');
      socket.off('suggestionMade');
      socket.off('accusationMade');
      socket.off('gameEnded');
      socket.off('error');
    };
  }, []);

  const joinGame = (playerData) => {
    socket.emit('joinGame', playerData);
  };

  const markReady = () => {
    socket.emit('playerReady');
    setMessage('Marked as ready! Waiting for other players...');
  };

  const makeMove = (destination) => {
    socket.emit('makeMove', { destination });
    setError('');
  };

  const makeSuggestion = (suggestionData) => {
    socket.emit('makeSuggestion', suggestionData);
    setError('');
  };

  const makeAccusation = (accusationData) => {
    socket.emit('makeAccusation', accusationData);
    setError('');
  };

  if (!isJoined) {
    return (
      <div className="App">
        <h1>Clue-Less</h1>
        <JoinForm onJoin={joinGame} />
        {error && <div className="error-message">{error}</div>}
      </div>
    );
  }

  const currentPlayer = gameState?.players[playerId];
  const isMyTurn = gameState?.currentPlayer === playerId;

  return (
    <div className="App">
      <div className="game-container">
        <h1>Clue-Less</h1>

        {message && <div className="success-message">{message}</div>}
        {error && <div className="error-message">{error}</div>}

        <div className="game-board">
          <PlayerInfo
            gameState={gameState}
            playerId={playerId}
            onMarkReady={markReady}
          />

          <GameBoard
            gameState={gameState}
            playerId={playerId}
            onMove={makeMove}
            isMyTurn={isMyTurn}
          />

          <ActionPanel
            gameState={gameState}
            playerId={playerId}
            isMyTurn={isMyTurn}
            currentPlayer={currentPlayer}
            onSuggestion={makeSuggestion}
            onAccusation={makeAccusation}
            onMove={makeMove}
          />
        </div>
      </div>
    </div>
  );
}

export default App;
